namespace sv_7096e1c60413428f98af26b0c0941056.Services;

public record UserProfile(string DisplayName, string Email, string AvatarUrl, string Bio);
public record NotificationPrefs(bool EmailNotifications, bool PushNotifications, bool WeeklyDigest, List<string> MutedChannels);
public record SecuritySettings(bool TwoFactorEnabled, DateTime? LastPasswordChange, List<ActiveSession> Sessions);
public record ActiveSession(string Id, string Device, string Location, DateTime LastActive);
public record AppearanceSettings(string Theme, string FontSize, string Language, bool CompactMode);

public interface ISettingsService
{
    Task<UserProfile> GetProfileAsync();
    Task SaveProfileAsync(UserProfile profile);
    Task<NotificationPrefs> GetNotificationPrefsAsync();
    Task SaveNotificationPrefsAsync(NotificationPrefs prefs);
    Task<SecuritySettings> GetSecuritySettingsAsync();
    Task ChangePasswordAsync(string currentPassword, string newPassword);
    Task RevokeSessionAsync(string sessionId);
    Task<AppearanceSettings> GetAppearanceAsync();
    Task SaveAppearanceAsync(AppearanceSettings settings);
}

@namespace sv_7096e1c60413428f98af26b0c0941056.Components.Pages.Settings

<nav class="settings-sidebar">
    <ul class="settings-nav">
        @foreach (var section in Sections)
        {
            <li class="settings-nav-item @(section == ActiveSection ? "active" : "")"
                @onclick="() => OnSectionChanged.InvokeAsync(section)">
                <span class="nav-icon">@GetIcon(section)</span>
                <span class="nav-label">@section</span>
            </li>
        }
    </ul>
</nav>

@code {
    [Parameter, EditorRequired]
    public string ActiveSection { get; set; } = "";

    [Parameter, EditorRequired]
    public EventCallback<string> OnSectionChanged { get; set; }

    private static readonly string[] Sections = ["Profile", "Notifications", "Security", "Appearance"];

    private static string GetIcon(string section) => section switch
    {
        "Profile" => "👤",
        "Notifications" => "🔔",
        "Security" => "🔒",
        "Appearance" => "🎨",
        _ => "⚙️"
    };
}

@namespace sv_7096e1c60413428f98af26b0c0941056.Components.Pages.Settings
@using sv_7096e1c60413428f98af26b0c0941056.Services

<div class="settings-section">
    <h2>Profile Settings</h2>

    @if (_profile is null)
    {
        <p class="loading">Loading profile...</p>
        return;
    }

    <div class="avatar-preview">
        <img src="@_displayName" alt="Avatar" class="avatar-img" onerror="this.style.display='none'" />
        @* Show avatar URL for reference *@
        <div class="avatar-url">
            <label>Avatar URL</label>
            <span>@_avatarUrl</span>
        </div>
    </div>

    <div class="form-group">
        <label for="displayName">Display Name</label>
        <input id="displayName" type="text" @bind="_displayName" @bind:event="oninput" class="form-control" />
    </div>

    <div class="form-group">
        <label for="email">Email</label>
        <input id="email" type="email" @bind="_email" @bind:event="oninput" class="form-control" />
    </div>

    <div class="form-group">
        <label for="bio">Bio</label>
        <textarea id="bio" @bind="_bio" @bind:event="oninput" class="form-control" rows="4"></textarea>
    </div>

    <div class="form-actions">
        <button class="btn btn-primary" @onclick="SaveAsync" disabled="@_saving">
            @(_saving ? "Saving..." : "Save Changes")
        </button>
        <button class="btn btn-secondary" @onclick="Discard" disabled="@_saving">
            Discard Changes
        </button>
    </div>

    @if (!string.IsNullOrEmpty(_message))
    {
        <div class="toast-message @_messageClass">@_message</div>
    }
</div>

@code {
    [Parameter, EditorRequired]
    public ISettingsService SettingsService { get; set; } = default!;

    private UserProfile? _profile;
    private string _displayName = "";
    private string _email = "";
    private string _avatarUrl = "";
    private string _bio = "";
    private bool _saving;
    private string _message = "";
    private string _messageClass = "";

    protected override async Task OnInitializedAsync()
    {
        _profile = await SettingsService.GetProfileAsync();
        LoadFromProfile(_profile);
    }

    private void LoadFromProfile(UserProfile profile)
    {
        _displayName = profile.DisplayName;
        _email = profile.Email;
        _avatarUrl = profile.AvatarUrl;
        _bio = profile.Bio;
    }

    private async Task SaveAsync()
    {
        _saving = true;
        _message = "";
        try
        {
            var updated = new UserProfile(_displayName, _email, _avatarUrl, _bio);
            await SettingsService.SaveProfileAsync(updated);
            _profile = updated;
            _message = "Profile saved successfully!";
            _messageClass = "toast-success";
        }
        catch (Exception ex)
        {
            _message = $"Error saving profile: {ex.Message}";
            _messageClass = "toast-error";
        }
        finally
        {
            _saving = false;
        }
    }

    private void Discard()
    {
        if (_profile is not null)
        {
            LoadFromProfile(_profile);
            _message = "Changes discarded.";
            _messageClass = "toast-info";
        }
    }
}

@namespace sv_7096e1c60413428f98af26b0c0941056.Components.Pages.Settings
@using sv_7096e1c60413428f98af26b0c0941056.Services

<div class="settings-section">
    <h2>Notification Preferences</h2>

    @if (_prefs is null)
    {
        <p class="loading">Loading preferences...</p>
        return;
    }

    <div class="toggle-group">
        <label class="toggle-label">
            <input type="checkbox" @bind="_emailNotifications" class="toggle-input" />
            <span class="toggle-switch"></span>
            <span>Email Notifications</span>
        </label>

        <label class="toggle-label">
            <input type="checkbox" @bind="_pushNotifications" class="toggle-input" />
            <span class="toggle-switch"></span>
            <span>Push Notifications</span>
        </label>

        <label class="toggle-label">
            <input type="checkbox" @bind="_weeklyDigest" class="toggle-input" />
            <span class="toggle-switch"></span>
            <span>Weekly Digest</span>
        </label>
    </div>

    <div class="channels-section">
        <h3>Muted Channels</h3>
        @if (_allChannels.Count == 0)
        {
            <p class="text-muted">No channels available.</p>
        }
        else
        {
            <ul class="channel-list">
                @foreach (var channel in _allChannels)
                {
                    <li class="channel-item">
                        <label>
                            <input type="checkbox"
                                   checked="@_mutedChannels.Contains(channel)"
                                   @onchange="e => ToggleChannel(channel, (bool)e.Value!)" />
                            <span>@channel</span>
                        </label>
                    </li>
                }
            </ul>
        }
    </div>

    <div class="form-actions">
        <button class="btn btn-primary" @onclick="SaveAsync" disabled="@_saving">
            @(_saving ? "Saving..." : "Save Preferences")
        </button>
    </div>

    @if (!string.IsNullOrEmpty(_message))
    {
        <div class="toast-message @_messageClass">@_message</div>
    }
</div>

@code {
    [Parameter, EditorRequired]
    public ISettingsService SettingsService { get; set; } = default!;

    private NotificationPrefs? _prefs;
    private bool _emailNotifications;
    private bool _pushNotifications;
    private bool _weeklyDigest;
    private HashSet<string> _mutedChannels = new();
    private List<string> _allChannels = new() { "general", "announcements", "random", "engineering", "design" };
    private bool _saving;
    private string _message = "";
    private string _messageClass = "";

    protected override async Task OnInitializedAsync()
    {
        _prefs = await SettingsService.GetNotificationPrefsAsync();
        _emailNotifications = _prefs.EmailNotifications;
        _pushNotifications = _prefs.PushNotifications;
        _weeklyDigest = _prefs.WeeklyDigest;
        _mutedChannels = new HashSet<string>(_prefs.MutedChannels);
    }

    private void ToggleChannel(string channel, bool muted)
    {
        if (muted)
            _mutedChannels.Add(channel);
        else
            _mutedChannels.Remove(channel);
    }

    private async Task SaveAsync()
    {
        _saving = true;
        _message = "";
        try
        {
            var updated = new NotificationPrefs(_emailNotifications, _pushNotifications, _weeklyDigest, _mutedChannels.ToList());
            await SettingsService.SaveNotificationPrefsAsync(updated);
            _prefs = updated;
            _message = "Preferences saved successfully!";
            _messageClass = "toast-success";
        }
        catch (Exception ex)
        {
            _message = $"Error: {ex.Message}";
            _messageClass = "toast-error";
        }
        finally
        {
            _saving = false;
        }
    }
}

@namespace sv_7096e1c60413428f98af26b0c0941056.Components.Pages.Settings
@using sv_7096e1c60413428f98af26b0c0941056.Services

<div class="settings-section">
    <h2>Security Settings</h2>

    @if (_settings is null)
    {
        <p class="loading">Loading security settings...</p>
        return;
    }

    <!-- Change Password Panel -->
    <div class="expandable-panel">
        <button class="panel-header" @onclick="() => _passwordPanelOpen = !_passwordPanelOpen">
            <span>Change Password</span>
            <span class="expand-icon">@(_passwordPanelOpen ? "▼" : "▶")</span>
        </button>

        @if (_passwordPanelOpen)
        {
            <div class="panel-body">
                <div class="form-group">
                    <label for="currentPassword">Current Password</label>
                    <input id="currentPassword" type="password" @bind="_currentPassword" class="form-control" />
                </div>
                <div class="form-group">
                    <label for="newPassword">New Password</label>
                    <input id="newPassword" type="password" @bind="_newPassword" class="form-control" />
                </div>
                <div class="form-group">
                    <label for="confirmPassword">Confirm Password</label>
                    <input id="confirmPassword" type="password" @bind="_confirmPassword" class="form-control" />
                </div>
                <button class="btn btn-primary" @onclick="ChangePasswordAsync" disabled="@_changingPassword">
                    @(_changingPassword ? "Updating..." : "Update Password")
                </button>
                @if (!string.IsNullOrEmpty(_passwordMessage))
                {
                    <div class="toast-message @_passwordMessageClass">@_passwordMessage</div>
                }
            </div>
        }
    </div>

    <!-- Two-Factor Authentication -->
    <div class="tfa-section">
        <h3>Two-Factor Authentication</h3>
        <div class="tfa-status">
            <span class="status-indicator @(_settings.TwoFactorEnabled ? "status-enabled" : "status-disabled")"></span>
            <span>@(_settings.TwoFactorEnabled ? "Enabled" : "Disabled")</span>
        </div>
        @if (_settings.LastPasswordChange.HasValue)
        {
            <p class="text-muted">Last password change: @_settings.LastPasswordChange.Value.ToString("MMMM dd, yyyy")</p>
        }
    </div>

    <!-- Active Sessions -->
    <div class="sessions-section">
        <h3>Active Sessions</h3>
        @if (_settings.Sessions.Count == 0)
        {
            <p class="text-muted">No active sessions.</p>
        }
        else
        {
            <table class="sessions-table">
                <thead>
                    <tr>
                        <th>Device</th>
                        <th>Location</th>
                        <th>Last Active</th>
                        <th>Actions</th>
                    </tr>
                </thead>
                <tbody>
                    @foreach (var session in _settings.Sessions)
                    {
                        <tr>
                            <td>@session.Device</td>
                            <td>@session.Location</td>
                            <td>@session.LastActive.ToString("g")</td>
                            <td>
                                @if (session != _settings.Sessions.First())
                                {
                                    <button class="btn btn-danger btn-sm"
                                            @onclick="() => ConfirmRevoke(session)">
                                        Revoke
                                    </button>
                                }
                                else
                                {
                                    <span class="badge-current">Current</span>
                                }
                            </td>
                        </tr>
                    }
                </tbody>
            </table>
        }
    </div>

    <!-- Revoke Confirmation Dialog -->
    @if (_sessionToRevoke is not null)
    {
        <div class="modal-overlay" @onclick="CancelRevoke">
            <div class="modal-dialog" @onclick:stopPropagation="true">
                <h4>Revoke Session</h4>
                <p>Are you sure you want to revoke the session on <strong>@_sessionToRevoke.Device</strong> from <strong>@_sessionToRevoke.Location</strong>?</p>
                <div class="modal-actions">
                    <button class="btn btn-danger" @onclick="RevokeSessionAsync" disabled="@_revoking">
                        @(_revoking ? "Revoking..." : "Revoke")
                    </button>
                    <button class="btn btn-secondary" @onclick="CancelRevoke" disabled="@_revoking">Cancel</button>
                </div>
            </div>
        </div>
    }

    @if (!string.IsNullOrEmpty(_message))
    {
