@namespace sv_7096e1c60413428f98af26b0c0941056.Components.Pages.Settings

<nav class="settings-sidebar">
    <ul class="settings-nav">
        @foreach (var section in Sections)
        {
            <li class="settings-nav-item @(section == ActiveSection ? "active" : "")"
                @onclick="() => OnSectionChanged.InvokeAsync(section)">
                <span class="nav-icon">@GetIcon(section)</span>
                <span class="nav-label">@section</span>
            </li>
        }
    </ul>
</nav>

@code {
    [Parameter, EditorRequired]
    public string ActiveSection { get; set; } = "";

    [Parameter, EditorRequired]
    public EventCallback<string> OnSectionChanged { get; set; }

    private static readonly string[] Sections = ["Profile", "Notifications", "Security", "Appearance"];

    private static string GetIcon(string section) => section switch
    {
        "Profile" => "👤",
        "Notifications" => "🔔",
        "Security" => "🔒",
        "Appearance" => "🎨",
        _ => "⚙️"
    };
}

@namespace sv_7096e1c60413428f98af26b0c0941056.Components.Pages.Settings
@using sv_7096e1c60413428f98af26b0c0941056.Services

<div class="settings-section">
    <h2>Profile Settings</h2>

    @if (_profile is null)
    {
        <p class="loading">Loading profile...</p>
        return;
    }

    <div class="avatar-preview">
        <img src="@_displayName" alt="Avatar" class="avatar-img" onerror="this.style.display='none'" />
        @* Show avatar URL for reference *@
        <div class="avatar-url">
            <label>Avatar URL</label>
            <span>@_avatarUrl</span>
        </div>
    </div>

    <div class="form-group">
        <label for="displayName">Display Name</label>
        <input id="displayName" type="text" @bind="_displayName" @bind:event="oninput" class="form-control" />
    </div>

    <div class="form-group">
        <label for="email">Email</label>
        <input id="email" type="email" @bind="_email" @bind:event="oninput" class="form-control" />
    </div>

    <div class="form-group">
        <label for="bio">Bio</label>
        <textarea id="bio" @bind="_bio" @bind:event="oninput" class="form-control" rows="4"></textarea>
    </div>

    <div class="form-actions">
        <button class="btn btn-primary" @onclick="SaveAsync" disabled="@_saving">
            @(_saving ? "Saving..." : "Save Changes")
        </button>
        <button class="btn btn-secondary" @onclick="Discard" disabled="@_saving">
            Discard Changes
        </button>
    </div>

    @if (!string.IsNullOrEmpty(_message))
    {
        <div class="toast-message @_messageClass">@_message</div>
    }
</div>

@code {
    [Parameter, EditorRequired]
    public ISettingsService SettingsService { get; set; } = default!;

    private UserProfile? _profile;
    private string _displayName = "";
    private string _email = "";
    private string _avatarUrl = "";
    private string _bio = "";
    private bool _saving;
    private string _message = "";
    private string _messageClass = "";

    protected override async Task OnInitializedAsync()
    {
        _profile = await SettingsService.GetProfileAsync();
        LoadFromProfile(_profile);
    }

    private void LoadFromProfile(UserProfile profile)
    {
        _displayName = profile.DisplayName;
        _email = profile.Email;
        _avatarUrl = profile.AvatarUrl;
        _bio = profile.Bio;
    }

    private async Task SaveAsync()
    {
        _saving = true;
        _message = "";
        try
        {
            var updated = new UserProfile(_displayName, _email, _avatarUrl, _bio);
            await SettingsService.SaveProfileAsync(updated);
            _profile = updated;
            _message = "Profile saved successfully!";
            _messageClass = "toast-success";
        }
        catch (Exception ex)
        {
            _message = $"Error saving profile: {ex.Message}";
            _messageClass = "toast-error";
        }
        finally
        {
            _saving = false;
        }
    }

    private void Discard()
    {
        if (_profile is not null)
        {
            LoadFromProfile(_profile);
            _message = "Changes discarded.";
            _messageClass = "toast-info";
        }
    }
}

