@namespace sv_7096e1c60413428f98af26b0c0941056.Components.Pages.Settings
@using sv_7096e1c60413428f98af26b0c0941056.Services

<div class="settings-section">
    <h2>Notification Preferences</h2>

    @if (_prefs is null)
    {
        <p class="loading">Loading preferences...</p>
        return;
    }

    <div class="toggle-group">
        <label class="toggle-label">
            <input type="checkbox" @bind="_emailNotifications" class="toggle-input" />
            <span class="toggle-switch"></span>
            <span>Email Notifications</span>
        </label>

        <label class="toggle-label">
            <input type="checkbox" @bind="_pushNotifications" class="toggle-input" />
            <span class="toggle-switch"></span>
            <span>Push Notifications</span>
        </label>

        <label class="toggle-label">
            <input type="checkbox" @bind="_weeklyDigest" class="toggle-input" />
            <span class="toggle-switch"></span>
            <span>Weekly Digest</span>
        </label>
    </div>

    <div class="channels-section">
        <h3>Muted Channels</h3>
        @if (_allChannels.Count == 0)
        {
            <p class="text-muted">No channels available.</p>
        }
        else
        {
            <ul class="channel-list">
                @foreach (var channel in _allChannels)
                {
                    <li class="channel-item">
                        <label>
                            <input type="checkbox"
                                   checked="@_mutedChannels.Contains(channel)"
                                   @onchange="e => ToggleChannel(channel, (bool)e.Value!)" />
                            <span>@channel</span>
                        </label>
                    </li>
                }
            </ul>
        }
    </div>

    <div class="form-actions">
        <button class="btn btn-primary" @onclick="SaveAsync" disabled="@_saving">
            @(_saving ? "Saving..." : "Save Preferences")
        </button>
    </div>

    @if (!string.IsNullOrEmpty(_message))
    {
        <div class="toast-message @_messageClass">@_message</div>
    }
</div>

@code {
    [Parameter, EditorRequired]
    public ISettingsService SettingsService { get; set; } = default!;

    private NotificationPrefs? _prefs;
    private bool _emailNotifications;
    private bool _pushNotifications;
    private bool _weeklyDigest;
    private HashSet<string> _mutedChannels = new();
    private List<string> _allChannels = new() { "general", "announcements", "random", "engineering", "design" };
    private bool _saving;
    private string _message = "";
    private string _messageClass = "";

    protected override async Task OnInitializedAsync()
    {
        _prefs = await SettingsService.GetNotificationPrefsAsync();
        _emailNotifications = _prefs.EmailNotifications;
        _pushNotifications = _prefs.PushNotifications;
        _weeklyDigest = _prefs.WeeklyDigest;
        _mutedChannels = new HashSet<string>(_prefs.MutedChannels);
    }

    private void ToggleChannel(string channel, bool muted)
    {
        if (muted)
            _mutedChannels.Add(channel);
        else
            _mutedChannels.Remove(channel);
    }

    private async Task SaveAsync()
    {
        _saving = true;
        _message = "";
        try
        {
            var updated = new NotificationPrefs(_emailNotifications, _pushNotifications, _weeklyDigest, _mutedChannels.ToList());
            await SettingsService.SaveNotificationPrefsAsync(updated);
            _prefs = updated;
            _message = "Preferences saved successfully!";
            _messageClass = "toast-success";
        }
        catch (Exception ex)
        {
            _message = $"Error: {ex.Message}";
            _messageClass = "toast-error";
        }
        finally
        {
            _saving = false;
        }
    }
}

