@namespace sv_7096e1c60413428f98af26b0c0941056.Components.Pages.Settings
@using sv_7096e1c60413428f98af26b0c0941056.Services

<div class="settings-section">
    <h2>Appearance</h2>

    @if (_settings is null)
    {
        <p class="loading">Loading appearance settings...</p>
        return;
    }

    <!-- Theme Selector -->
    <div class="form-group">
        <label><strong>Theme</strong></label>
        <div class="radio-group">
            @foreach (var theme in _themes)
            {
                <label class="radio-label">
                    <input type="radio" name="theme" value="@theme"
                           checked="@(_theme == theme)"
                           @onchange="() => _theme = theme" />
                    <span>@theme</span>
                </label>
            }
        </div>
    </div>

    <!-- Font Size Selector -->
    <div class="form-group">
        <label><strong>Font Size</strong></label>
        <div class="radio-group">
            @foreach (var size in _fontSizes)
            {
                <label class="radio-label">
                    <input type="radio" name="fontSize" value="@size"
                           checked="@(_fontSize == size)"
                           @onchange="() => _fontSize = size" />
                    <span>@size</span>
                </label>
            }
        </div>
    </div>

    <!-- Language Dropdown -->
    <div class="form-group">
        <label for="language"><strong>Language</strong></label>
        <select id="language" @bind="_language" class="form-control">
            @foreach (var lang in _languages)
            {
                <option value="@lang.Key">@lang.Value</option>
            }
        </select>
    </div>

    <!-- Compact Mode -->
    <div class="form-group">
        <label class="toggle-label">
            <input type="checkbox" @bind="_compactMode" class="toggle-input" />
            <span class="toggle-switch"></span>
            <span><strong>Compact Mode</strong></span>
        </label>
    </div>

    <!-- Live Preview -->
    <div class="preview-area @GetPreviewClasses()">
        <h4>Live Preview</h4>
        <p class="preview-text">This is how your content will look with the selected settings.</p>
        <div class="preview-card">
            <span class="preview-title">Sample Card</span>
            <span class="preview-body">Card content with your chosen theme and font size.</span>
        </div>
    </div>

    <div class="form-actions">
        <button class="btn btn-primary" @onclick="SaveAsync" disabled="@_saving">
            @(_saving ? "Saving..." : "Save")
        </button>
    </div>

    @if (!string.IsNullOrEmpty(_message))
    {
        <div class="toast-message @_messageClass">@_message</div>
    }
</div>

@code {
    [Parameter, EditorRequired]
    public ISettingsService SettingsService { get; set; } = default!;

    private AppearanceSettings? _settings;
    private string _theme = "System";
    private string _fontSize = "Medium";
    private string _language = "en";
    private bool _compactMode;
    private bool _saving;
    private string _message = "";
    private string _messageClass = "";

    private static readonly string[] _themes = ["Light", "Dark", "System"];
    private static readonly string[] _fontSizes = ["Small", "Medium", "Large"];
    private static readonly Dictionary<string, string> _languages = new()
    {
        ["en"] = "English",
        ["es"] = "Spanish",
        ["fr"] = "French",
        ["de"] = "German",
        ["ja"] = "Japanese",
        ["zh"] = "Chinese"
    };

    protected override async Task OnInitializedAsync()
    {
        _settings = await SettingsService.GetAppearanceAsync();
        _theme = _settings.Theme;
        _fontSize = _settings.FontSize;
        _language = _settings.Language;
        _compactMode = _settings.CompactMode;
    }

    private string GetPreviewClasses()
    {
        var classes = $"preview-theme-{_theme.ToLowerInvariant()} preview-font-{_fontSize.ToLowerInvariant()}";
        if (_compactMode) classes += " preview-compact";
        return classes;
    }

    private async Task SaveAsync()
    {
        _saving = true;
        _message = "";
        try
        {
            var updated = new AppearanceSettings(_theme, _fontSize, _language, _compactMode);
            await SettingsService.SaveAppearanceAsync(updated);
            _settings = updated;
            _message = "Appearance settings saved!";
            _messageClass = "toast-success";
        }
        catch (Exception ex)
        {
            _message = $"Error: {ex.Message}";
            _messageClass = "toast-error";
        }
        finally
        {
            _saving = false;
        }
    }
}

